WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_no, DATE_TRUNC('YEAR', txn_time) AS year_start, MIN(txn_time) AS first_txn_time, MAX(txn_time) AS ended_at, AVG(session_no) AS avg_session_no, SUM(CASE WHEN merchant = 'Shell' THEN amount ELSE 0 END) AS shell_amount, SUM(is_new_session) AS total_is_new_session, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes FROM islands GROUP BY session_no, DATE_TRUNC('YEAR', txn_time);
